    def numberOfPowerfulInt(self, start: int, finish: int, limit: int, s: str) -> int:
        def count_powerful_up_to(n):
            if n < int(s):
                return 0

            str_n = str(n)
            len_s = len(s)
            len_n = len(str_n)

            # If the number has fewer digits than s, impossible
            if len_n < len_s:
                return 0

            # If the number has same digits as s, check if it ends with s
            if len_n == len_s:
                str_n_val = int(str_n)
                if str_n_val >= int(s):
                    # Check if it ends with s and all digits <= limit
                    if str_n.endswith(s) and all(int(d) <= limit for d in str_n):
                        return 1
                return 0

            # For numbers with more digits, they are of form: prefix + s
            # prefix has (len_n - len_s) digits
            prefix_len = len_n - len_s

            # The number is: prefix * (10^len_s) + int(s)
            # We need: prefix * (10^len_s) + int(s) <= n
            # So: prefix <= (n - int(s)) / (10^len_s)

            suffix_value = int(s)
            if suffix_value > n:
                return 0

            max_prefix = (n - suffix_value) // (10 ** len_s)

            # If max_prefix is negative, no valid prefixes
            if max_prefix < 0:
                return 0

            # Count how many numbers with digits <= limit can form the prefix
            # up to max_prefix

            def count_valid_prefixes(max_val):
                if max_val <= 0:
                    return 0

                # Convert to string
                str_max = str(max_val)
                digits = len(str_max)

                # DP with memoization
                from functools import lru_cache

                @lru_cache(maxsize=None)
                def dp(pos, tight):
                    if pos == digits:
                        return 1

                    result = 0
                    # Upper bound for current digit
                    upper = int(str_max[pos]) if tight else 9

                    # We can use digits from 0 to min(limit, upper)
                    max_digit = min(limit, upper)

                    for d in range(0, max_digit + 1):
                        new_tight = tight and (d == upper)
                        result += dp(pos + 1, new_tight)

                    return result

                return dp(0, True)

            return count_valid_prefixes(max_prefix)

        return count_powerful_up_to(finish) - count_powerful_up_to(start - 1)

